// Generated by scripts/generate_v5_tests.py; edit tests/v5-cases.json.
mod support;

fn assert_memory_balanced(stderr: &[u8]) {
    let report = String::from_utf8_lossy(stderr);
    let mut fields = report.split_whitespace();
    assert_eq!(fields.next(), Some("NACRE_MEMORY"), "{report}");
    let allocations = fields.next().unwrap().strip_prefix("allocations=").unwrap();
    let frees = fields.next().unwrap().strip_prefix("frees=").unwrap();
    assert_eq!(allocations, frees, "{report}");
    assert_eq!(fields.next(), Some("live=0"), "{report}");
    assert_eq!(fields.next(), None, "{report}");
}

#[test]
fn example_collections() {
    let source = "void main() {\n    List<int> scores = new List<int>();\n    scores.add(10);\n    scores.add(20);\n    scores.add(12);\n    int sum = 0;\n    int i = 0;\n    while (i < scores.size()) {\n        sum = sum + scores.get(i);\n        i = i + 1;\n    }\n    Text message = new Text(\"Somme = \");\n    message.appendInt(sum);\n    message.print();\n    println(scores.remove(1));\n    println(scores.pop());\n    println(scores.size());\n}\n";
    let program = support::compile(source, &["-DNACRE_MEMORY_STATS"]).unwrap();
    let result = program.output().unwrap();
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    assert_eq!(result.stdout, "Somme = 42\n20\n12\n1\n".as_bytes());
    assert_memory_balanced(&result.stderr);
}

#[test]
fn example_owned_list() {
    let source = "interface Named {\n    readonly String name();\n}\nclass Person implements Named {\n    private String value;\n    public Person(String value) { this.value = value; }\n    public readonly String name() { return this.value; }\n}\nvoid main() {\n    List<Named> people = new List<Named>();\n    Person alice = new Person(\"Alice\");\n    people.add(alice); // Transfert; alice n'est plus utilisable.\n    people.add(new Person(\"Bob\"));\n    Named first = people.remove(0);\n    println(first.name());\n    // Vider la liste detruit Bob, mais pas Alice extraite par remove.\n    people.clear();\n    println(first.name());\n    println(people.isEmpty());\n}\n";
    let program = support::compile(source, &["-DNACRE_MEMORY_STATS"]).unwrap();
    let result = program.output().unwrap();
    assert!(result.status.success(), "{}", String::from_utf8_lossy(&result.stderr));
    assert_eq!(result.stdout, "Alice\nAlice\ntrue\n".as_bytes());
    assert_memory_balanced(&result.stderr);
}

