fn text_negative_index() {
    let source = "void main(){Text t=new Text(\"x\");println(t.byteAt(-1));}";
    let program = support::compile(source, &[]).unwrap();
    let result = program.output().unwrap();
    assert_eq!(result.status.code(), Some(70));
    assert!(String::from_utf8_lossy(&result.stderr).contains("[1:"));
}

#[test]
fn text_empty_index() {
    let source = "void main(){Text t=new Text(\"\");println(t.byteAt(0));}";
    let program = support::compile(source, &[]).unwrap();
    let result = program.output().unwrap();
    assert_eq!(result.status.code(), Some(70));
    assert!(String::from_utf8_lossy(&result.stderr).contains("[1:"));
}
